/* @autogenerated */
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { TemplateRepository } from 'app/features/template/template/repository/template-repository.service';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import { take, map } from 'rxjs';
import { TemplateAsset } from 'app/features/template/template-asset/model/template-asset.model';
import {
  TEMPLATE_ASSET_EXCEL_COLUMNS,
  TEMPLATE_ASSET_EXCEL_SENSITIVE,
} from 'app/features/template/template-asset/model/template-asset-excel-columns';
import { TemplateAssetRepository } from 'app/features/template/template-asset/repository/template-asset-repository.service';
import { Component, inject } from '@angular/core';

@Component({
  selector: 'template-asset-view-export-action',
  standalone: false,
  templateUrl: './template-asset-view-export-action.component.html',
})
export class TemplateAssetViewExportActionComponent extends BaseExportAction<TemplateAsset> {
  protected readonly scope = 'template/template-asset';
  protected readonly repository = inject(TemplateAssetRepository);
  private readonly templateRepository = inject(TemplateRepository);
  private readonly tenantRepository = inject(TenantRepository);

  readonly definition: ExportDefinition<TemplateAsset> = {
    name: 'template.template-asset',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: TEMPLATE_ASSET_EXCEL_COLUMNS,
    sensitive: TEMPLATE_ASSET_EXCEL_SENSITIVE,
    references: {
      template: {
        names: (refs) =>
          this.templateRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.code ?? '')]))),
          ),
      },
      tenant: {
        names: (refs) =>
          this.tenantRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.name ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
